-- ==============================================================================
-- A LITTLE WORLD OF JUU — FULL SETUP & SEED DATA
-- Buckets: 'image-of_juu' and 'voice_notes'
-- Run this in Supabase Dashboard: SQL Editor -> New Query -> Run
-- ==============================================================================

-- 1. STORAGE POLICIES FOR 'image-of_juu' AND 'voice_notes'
DROP POLICY IF EXISTS "Public read image-of_juu" ON storage.objects;
CREATE POLICY "Public read image-of_juu" ON storage.objects FOR SELECT USING (bucket_id = 'image-of_juu');

DROP POLICY IF EXISTS "Public read voice_notes" ON storage.objects;
CREATE POLICY "Public read voice_notes" ON storage.objects FOR SELECT USING (bucket_id = 'voice_notes');

DROP POLICY IF EXISTS "Allow upload to image-of_juu" ON storage.objects;
CREATE POLICY "Allow upload to image-of_juu" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'image-of_juu');

DROP POLICY IF EXISTS "Allow upload to voice_notes" ON storage.objects;
CREATE POLICY "Allow upload to voice_notes" ON storage.objects FOR INSERT WITH CHECK (bucket_id = 'voice_notes');

DROP POLICY IF EXISTS "Allow delete in image-of_juu" ON storage.objects;
CREATE POLICY "Allow delete in image-of_juu" ON storage.objects FOR DELETE USING (bucket_id = 'image-of_juu');

DROP POLICY IF EXISTS "Allow delete in voice_notes" ON storage.objects;
CREATE POLICY "Allow delete in voice_notes" ON storage.objects FOR DELETE USING (bucket_id = 'voice_notes');

-- 2. TABLE POLICIES FOR ADMIN WRITE ACCESS
DROP POLICY IF EXISTS "Admin manage timeline" ON public.timeline;
CREATE POLICY "Admin manage timeline" ON public.timeline FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage memories" ON public.memories;
CREATE POLICY "Admin manage memories" ON public.memories FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage letters" ON public.letters;
CREATE POLICY "Admin manage letters" ON public.letters FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage voice_notes" ON public.voice_notes;
CREATE POLICY "Admin manage voice_notes" ON public.voice_notes FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage promises" ON public.promises;
CREATE POLICY "Admin manage promises" ON public.promises FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage little_things" ON public.little_things;
CREATE POLICY "Admin manage little_things" ON public.little_things FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage future_dreams" ON public.future_dreams;
CREATE POLICY "Admin manage future_dreams" ON public.future_dreams FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Admin manage site_settings" ON public.site_settings;
CREATE POLICY "Admin manage site_settings" ON public.site_settings FOR ALL USING (true) WITH CHECK (true);

