INSERT INTO public.timeline ("id", "date", "displayDate", "title", "description", "photoUrl", "photoCaption", "category", "location", "ladduEmotion") VALUES ('timeline-1', '2025-09-19', '19 September 2025', 'Where Our Paths First Crossed', 'A hospital visit where destiny had an unexpected plan. Laddu accidentally hit Juu during their very first encounter — a clumsy, unforgettable spark that started everything.', 'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?q=80&w=800&auto=format&fit=crop', 'Placeholder Artistic Memory: Hospital Courtyard Moment', 'first_meet', 'Hospital Grounds', 'Startled, shy, and secretly memorable') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.timeline ("id", "date", "displayDate", "title", "description", "photoUrl", "photoCaption", "category", "location", "ladduEmotion") VALUES ('timeline-2', '2025-10-04', 'Early October 2025', 'The Conversations Began', 'What started as accidental became gradual daily conversations. Simple check-ins turned into late-night reflections, sharing little thoughts and feeling a rare comfort.', 'https://images.unsplash.com/photo-1518495973542-4542c06a5843?q=80&w=800&auto=format&fit=crop', 'Placeholder Artistic Memory: Words Floating In The Quiet Hours', 'growing_closer', 'Endless Phone Calls', 'Curious & warming up') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.timeline ("id", "date", "displayDate", "title", "description", "photoUrl", "photoCaption", "category", "location", "ladduEmotion") VALUES ('timeline-3', '2025-11-15', 'Mid November 2025', 'Words That Meant Something More', 'We started talking about real things — vulnerabilities, fears, family, dreams, and the kind of understanding we had both looked for. Silence was no longer awkward.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=800&auto=format&fit=crop', 'Placeholder Artistic Memory: Calm Waves & Honest Truths', 'deep_conversations', 'Late Evenings', 'Heard & softly understood') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.timeline ("id", "date", "displayDate", "title", "description", "photoUrl", "photoCaption", "category", "location", "ladduEmotion") VALUES ('timeline-4', '2025-12-28', 'Late December 2025', 'Falling In Love Without Realizing When', 'There wasn’t just one big movie moment — it was the sum of so many small gestures, smiles, shared sighs, and realising you were the first person I wanted to tell everything to.', 'https://images.unsplash.com/photo-1519751138087-5bf79df62d5b?q=80&w=800&auto=format&fit=crop', 'Placeholder Artistic Memory: Midnight Lights & Soft Warmth', 'falling_in_love', 'In Every Thought', 'Precious, cherished & loved') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.timeline ("id", "date", "displayDate", "title", "description", "photoUrl", "photoCaption", "category", "location", "ladduEmotion") VALUES ('timeline-5', '2026-02-14', 'Present & Beyond', 'Through Memories, Support & Challenges', 'Learning how to love each other through both sweet days and stormy ones. Committing to listen, apologize, protect each other’s peace, and stand by your dreams.', 'https://images.unsplash.com/photo-1534447677768-be436bb09401?q=80&w=800&auto=format&fit=crop', 'Placeholder Artistic Memory: Stars In Deep Navy Skies', 'milestone', 'Every Chapter Ahead', 'Grounded & hopeful') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-1', 'The First Accidental Encounter', '2025-09-19', '19 September 2025', 'Hospital Corridors', 'firsts', 'https://images.unsplash.com/photo-1516589178581-6cd7833ae3b2?q=80&w=1000&auto=format&fit=crop', 'Who would have known that accidentally hitting me would become the best accident of my life? (Placeholder artwork ready for private photo)', true, ARRAY['First Meet', 'Destiny', 'Hospital']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-2', 'Late Night Midnight Murmurs', '2025-10-24', 'October 2025', 'Whispered Audio Calls', 'quiet_moments', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?q=80&w=1000&auto=format&fit=crop', 'When sleep was secondary because listening to your voice talking about your day was the calmest place in the world.', true, ARRAY['Night Calls', 'Voice', 'Comfort']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-3', 'Your Shy Little Smile', '2025-11-10', 'November 2025', 'A Fleeting Glance', 'candid', 'https://images.unsplash.com/photo-1494774157365-9e04c6720e47?q=80&w=1000&auto=format&fit=crop', 'That particular way you look down and smile when you are teased. It melts all the heavy noise of the world.', true, ARRAY['Smile', 'Candid', 'Warmth']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-4', 'Study Notes & Big Dreams', '2025-12-05', 'December 2025', 'Desk Under Warm Lamp', 'special', 'https://images.unsplash.com/photo-1456513080510-7bf3a84b82f8?q=80&w=1000&auto=format&fit=crop', 'Watching how dedicated you are to your studies and your future. Never forget how smart, capable, and resilient you are.', true, ARRAY['Dreams', 'Education', 'Pride']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-5', 'A Breeze By The Water', '2026-01-14', 'January 2026', 'Coastal Evening', 'travel', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=1000&auto=format&fit=crop', 'Standing where the wind was cool and thinking about how much I want to make sure you always feel cherished and safe.', true, ARRAY['Ocean', 'Breeze', 'Reassurance']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.memories ("id", "title", "date", "displayDate", "location", "category", "imageUrl", "caption", "isPlaceholder", "tags") VALUES ('mem-6', 'The Silly Inside Jokes', '2026-02-01', 'February 2026', 'Every Random Chat', 'candid', 'https://images.unsplash.com/photo-1517841905240-472988babdf9?q=80&w=1000&auto=format&fit=crop', 'The way we laugh at things nobody else would ever understand. Those moments are pure gold.', true, ARRAY['Laughter', 'Inside Jokes', 'Joy']::TEXT[]) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-1', 'open-when-you-miss-me', 'Open When You Miss Me', 'For when the distance feels a little too loud', 'Missing Juu', '#C6A56B', ARRAY['Hey my Laduuu,', 'I know there are days when you wish I could just magically appear in front of you, pull a silly face to make you smile, or just sit quietly beside you so you do not have to say a single word.', 'Whenever the distance or silence feels a little too heavy, I want you to remember that missing each other is simply proof of something real we share. But please do not let longing turn into loneliness or sadness.', 'Close your eyes for three seconds. Take a slow, deep breath. I am thinking of you right now too, wishing you warmth and peace in your heart. You are carrying a piece of me with you everywhere you go.', 'I am always rooting for you, proud of you, and waiting to hear your voice soon.']::TEXT[], 'Forever in your corner, Juu ❤️', 'If you close your eyes right now, imagine me holding your hands, reminding you that I am right here in your corner...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-2', 'open-when-you-feel-alone', 'Open When You Feel Alone', 'Even in an empty room, you are deeply cherished', 'Feeling Alone', '#75485B', ARRAY['My dearest Laddu,', 'It is easy for the mind to play tricks on us when darkness settles in, or when people around us seem busy with their own worlds. You might feel like nobody understands the weight you carry.', 'I want you to know: your presence matters so much to me. The world is brighter, softer, and more meaningful because you are in it.', 'Even when we are not actively talking, my care for you does not pause or switch off. It is steady, patient, and real.', 'Put your hand over your heart. Feel that rhythm? That is life, resilience, and beauty. You are loved, you are valued, and you are never truly forgotten.']::TEXT[], 'Always beside you in spirit, Juu ❤️', 'You are never as alone as your overthinking wants you to believe. Your feelings matter, and you are loved...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-3', 'open-when-you-cry', 'Open When You Cry', 'Tears are not weakness; they are feelings needing release', 'Tears & Sorrow', '#202C40', ARRAY['Hey kutty,', 'If tears are falling right now, please do not wipe them away in frustration or feel like you are being "too dramatic" or "too soft". Crying is just the heart’s way of breathing out when words aren’t enough.', 'You carry so many expectations, thoughts, and worries on your shoulders. It is okay to put that heavy backpack down for a moment.', 'If I were right there, I would not rush to say "stop crying". I would give you a tissue, sit by you, hold your hand gently, and let you cry until the storm passed.', 'Drink a glass of water after reading this. Wash your face with cool water. You are going to be okay, one slow breath at a time.']::TEXT[], 'With all my gentleness, Juu ❤️', 'Let it out, kutty. You do not have to hold everything in or pretend to be unbreakable...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-4', 'open-when-you-doubt-yourself', 'Open When You Doubt Yourself', 'A reminder of the strength and brilliance inside you', 'Self-Doubt & Insecurity', '#C6A56B', ARRAY['Laduuu,', 'Pause right there. Stop the harsh voice in your head that is comparing you to others or telling you that you are not capable or smart enough.', 'I see how diligently you work. I see the quiet courage you bring to your studies, your goals, and the challenges life throws at you. You have walked through difficult days before, and you came out stronger every single time.', 'Doubt is just a visitor; it is not the truth about who you are. Your potential is immense, your mind is bright, and your heart is sincere.', 'Believe in yourself the way I believe in you. Lift your chin up. You’ve got this.']::TEXT[], 'Your biggest fan, Juu ❤️', 'Look at how far you have already come. Don’t let a temporary stumble erase your incredible capabilities...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-5', 'open-when-you-are-stressed', 'Open When You Are Stressed', 'Everything does not need to be solved in this single hour', 'Stress & Overwhelm', '#182338', ARRAY['Hey my hardworking Laddu,', 'Notice where your tension is right now: are your shoulders hunched? Is your jaw clenched? Let them relax right this second.', 'Whatever deadline, exam, assignment, or family tension is piling up — remember that life happens in small steps, not all at once. You do not have to solve the next five years of your life tonight.', 'Break it down into just the next single task. If even that is too much, take a 15-minute break. Make a warm cup of something you like, listen to a calming song, and reset.', 'Your mental peace and well-being will always matter more than rushing perfection.']::TEXT[], 'Breathe easy, Juu ❤️', 'Drop your shoulders away from your ears. Unclench your jaw. Breathe in for four seconds...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-6', 'open-when-you-cannot-sleep', 'Open When You Cannot Sleep', 'Rest your thoughts under this midnight sky', 'Sleepless Nights', '#101725', ARRAY['Hey sleep-resistant girl,', 'It is late, the world is quiet, and yet your thoughts are running a marathon. I know the feeling all too well.', 'I want you to make an agreement with yourself: whatever you are worrying about right now cannot be resolved at 2:00 AM. It will still be there tomorrow, but you will handle it ten times better with rest.', 'Put your phone aside on dim mode. Close your eyes. Picture a calm ocean shore under a navy sky with gentle waves washing up on smooth sand. The breeze is cool and quiet.', 'Rest your mind, Laddu. Sleep gently. I will see you in the morning.']::TEXT[], 'Goodnight sweet dreams, Juu ❤️', 'The night is not an interrogation room. Put the worries on pause until morning lights arrive...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-7', 'open-when-you-achieve-something', 'Open When You Achieve Something', 'Celebrate yourself! I am celebrating you from the bottom of my heart', 'Success & Celebration', '#C6A56B', ARRAY['YAYYY! MY PROUD LADUUU!', 'Whether this is an exam result, a completed project, a personal breakthrough, or simply surviving a week that demanded everything from you — CELEBRATE!', 'You worked for this. You put in the quiet hours when nobody was watching. Do not downplay your achievement or say "it was just luck". It was your effort, your focus, and your talent.', 'I am smiling so wide right now thinking of how happy and relieved you must feel. Treat yourself to your favorite snack today.', 'I am endlessly proud to know you and watch you flourish.']::TEXT[], 'Cheering the loudest for you, Juu 🎉❤️', 'YES! I knew you could do it! Take a victory dance and soak in your hard-earned pride...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-8', 'open-when-you-need-a-hug', 'Open When You Need a Hug', 'Wrap yourself in this warm blanket of reassurance', 'Craving Warmth & Comfort', '#75485B', ARRAY['Hey my soft kutty,', 'Sometimes words aren’t what we need — we just need that warm, safe physical embrace that lets us melt away our defenses.', 'Since I cannot wrap my arms around you in person right this moment, pull your blanket up tight, tuck your knees in, and let this letter be a gentle proxy.', 'Imagine me resting my chin lightly on your head, saying: "You are doing fine. You are safe. You are cared for."', 'Hold onto this warmth. You are precious beyond measure.']::TEXT[], 'A long, tight warm hug, Juu ❤️', 'Wrap your arms around yourself, squeeze tight, and imagine the warmest hug from me...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-9', 'open-when-you-are-angry-with-me', 'Open When You Are Angry With Me', 'When I have hurt you or made a mistake — I am listening', 'Anger & Frustration with Juu', '#202C40', ARRAY['Laddu,', 'If you are reading this because I upset you, said something insensitive, or failed to be the partner you deserved in an argument — please read this with an open heart.', 'I am not writing this to dismiss your feelings or explain away my mistakes. Your hurt is completely valid. If I caused you pain, I am genuinely sorry.', 'I promise you that I never want our arguments to turn into threats of leaving, cutting communication, or making you feel small. I want us to be a team that talks through differences, even when it is uncomfortable.', 'Take all the space you need to cool down. When you are ready, please tell me what you felt. I am ready to listen, learn, and do better.']::TEXT[], 'Humbly committed to getting it right, Juu', 'Your anger is valid. I do not want to defend my ego — I want to understand your hurt and make it right...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.letters ("id", "slug", "title", "subtitle", "triggerFeeling", "envelopeColor", "content", "closing", "previewExcerpt", "isCustomizedByJuu", "readCount") VALUES ('let-10', 'open-when-you-need-to-remember-how-special-you-are', 'Open When You Need to Remember How Special You Are', 'Never forget the rare light you carry into this world', 'Lost Sense of Worth', '#C6A56B', ARRAY['My dearest Laduuu,', 'If you ever start feeling ordinary, replaceable, or invisible, I want to stand in front of you and be your mirror.', 'You are special not because of superficial things, but because of who you are at your core: your sensitivity, the way you care deeply for people, your genuine laughter, your sharp wit, and your beautiful resilience.', 'Meeting you was not just a lucky date on a calendar; it changed how I see sincerity and care. You make ordinary moments feel like memories worth keeping forever.', 'Never shrink yourself to fit into smaller spaces. Shine proudly, kutty. You are one in an infinite galaxy.']::TEXT[], 'Admiring you always, Juu ❤️', 'In a world of billions of people, there is nobody with your exact heart, kindness, and spark...', true, 0) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "content" = EXCLUDED."content";
INSERT INTO public.voice_notes ("id", "title", "category", "categoryLabel", "duration", "durationSeconds", "caption", "audioUrl", "syntheticVoiceType", "isPlaceholder") VALUES ('voice-1', 'A Little Reassurance For Today', 'reassurance', 'A Little Reassurance', '02:18', 138, 'When your thoughts feel like a heavy cloud, press play and let me remind you of your quiet strength.', NULL, 'warm_reassurance', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.voice_notes ("id", "title", "category", "categoryLabel", "duration", "durationSeconds", "caption", "audioUrl", "syntheticVoiceType", "isPlaceholder") VALUES ('voice-2', 'When You Miss My Voice', 'miss_me', 'When You Miss Me', '01:45', 105, 'A gentle message recorded just for those quiet evenings when you wish I was sitting across from you.', NULL, 'gentle_whisper', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.voice_notes ("id", "title", "category", "categoryLabel", "duration", "durationSeconds", "caption", "audioUrl", "syntheticVoiceType", "isPlaceholder") VALUES ('voice-3', 'For When You Feel Low or Overwhelmed', 'feel_low', 'When You Feel Low', '03:02', 182, 'Take a breath with me. We will take this hour by hour, without rush and without fear.', NULL, 'calm_presence', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.voice_notes ("id", "title", "category", "categoryLabel", "duration", "durationSeconds", "caption", "audioUrl", "syntheticVoiceType", "isPlaceholder") VALUES ('voice-4', 'A Silly Reminder to Make You Smile', 'make_smile', 'When I Want to Make You Smile', '01:20', 80, 'A playful check-in to tease that grumpy pout off your face and bring out your real smile.', NULL, 'warm_reassurance', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.voice_notes ("id", "title", "category", "categoryLabel", "duration", "durationSeconds", "caption", "audioUrl", "syntheticVoiceType", "isPlaceholder") VALUES ('voice-5', 'Just a Random Midday Note from Juu', 'random', 'Random Message from Juu', '01:50', 110, 'No special reason — just checking if my Laduuu had her meal, drank water, and didn’t stress too much.', NULL, 'gentle_whisper', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "caption" = EXCLUDED."caption";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-1', 'Listening Instead of Assuming', 'Choosing patience over hasty conclusions.', 'I commit to asking questions and genuinely seeking to understand your perspective before forming a judgment or reacting in defensiveness.', 'communication', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-2', 'Communicating Instead of Threatening to Leave', 'Standing firm in commitment during stormy moments.', 'Disagreements happen, but our foundation should never be called into question. I promise to work through issues rather than threatening detachment.', 'communication', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-3', 'No Blocking or App Uninstall Threats', 'Eliminating fear tactics from our conflict resolution.', 'I will never use blocking, uninstalling apps, or vanishing as a weapon or threat during arguments. Respectful boundaries over emotional leverage, always.', 'consistency', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-4', 'Giving Time to Calm Down Without Abandonment', 'Space with assurance, never cold silence.', 'If either of us feels overwhelmed, we will pause respectfully with clear reassurance: "I love you, I need 20 minutes to breathe, and I am coming right back to talk."', 'patience', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-5', 'Discussing Difficult Feelings Respectfully', 'Creating a safe harbor where honesty is never punished.', 'You will never have to bottle up your hurt or fear that speaking your mind will cause a fight. Your feelings will be heard with dignity.', 'communication', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-6', 'Prioritizing Quality Time Together', 'Intentional presence in a busy world.', 'Making sure that busyness does not crowd out our connection. Setting aside real, unhurried time where you have my full undivided attention.', 'consistency', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-7', 'Championing Your Education & Dreams', 'Your ambitions are sacred to me.', 'Supporting your studies, encouraging your professional ambitions, and never making you feel like your personal growth takes a backseat.', 'dreams_support', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-8', 'Consistency Through Actions, Not Just Words', 'Showing up reliably every single day.', 'Promises mean nothing without daily reliability. I will demonstrate my care through how I treat you, how I listen, and how I follow through.', 'consistency', false, NULL, NULL, NULL, true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-diff-1', 'Accountability: The Beach Night Ride', 'Acknowledging the hurt of "neeye poiko" and choosing true safety.', 'I deeply regret that night when frustration took over and I said words that made you feel deserted, unwanted, or unsafe. You deserved protection, warmth, and steady companionship, not harsh words that left you questioning your place. I acknowledge that pain and promise never to let anger make you feel abandoned.', 'accountability', true, 'The Beach Night Ride Incident', 'Feeling discarded, unsafe, unwanted, and hurt by cold words in a vulnerable moment.', 'To always be your safe protector, to never utter words of abandonment in heat, and to ensure you always know you are wanted and cherished.', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.promises ("id", "title", "summary", "detail", "category", "isAccountabilityNote", "incidentTitle", "ladduFeelingAcknowledged", "juuCommitment", "isApprovedByJuu") VALUES ('prom-diff-2', 'Accountability: The Threat to End Communication', 'Acknowledging the threat of stopping talks and uninstalling apps.', 'During that argument, threatening to disconnect, cut communication, and uninstall apps was an unhealthy emotional reaction that hurt you deeply. You do not deserve to walk on eggshells or fear that expressing feelings will lead to sudden silence. I take full responsibility for that behavior and commit to open, mature dialogue.', 'accountability', true, 'The Argument Threatening Cut-Off & Uninstallation', 'Fear of sudden loss, emotional invalidation, anxiety over communication withdrawal.', 'To keep communication open, never use vanishing as an emotional lever, and work through disagreements with calm maturity.', true) ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "detail" = EXCLUDED."detail";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-1', 'nicknames', 'My Favorite Names For You', 'Laduuu, Kutty, My Little Moon, Drama Queen (affectionately), Miss Stubborn.', 'Sparkles', 'Sweet & Playful') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-2', 'about_laddu', 'Things Juu Adores About Laddu', 'The genuine sparkle in your eyes when you talk about things you love, your sharp intuition, your laugh that lights up any room, and your hidden soft heart.', 'Heart', 'Cherished') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-3', 'food', 'Food We Crave Together', 'Midnight snacks, warm crispy dosas, sweet cravings when stressed, and debating what to order for 45 minutes.', 'Coffee', 'Daily Cravings') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-4', 'songs', 'Melodies That Remind Me of Us', 'Quiet acoustic tunes, soulful midnight melodies, and songs that feel like slow breeze on a quiet drive.', 'Music', 'Soundtrack') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-5', 'habits', 'Juu''s Favourite Ways to Annoy Laddu 😂❤️', 'Constantly pulling her leg, teasing her for no reason, irritating her just to see her cute angry face, making silly jokes at the wrong time, and never missing a chance to make her say, "JUUUUU! 😤"', 'Smile', 'Honest Truth') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-6', 'jokes', 'Our Unspoken Hospital Joke', 'Who knew hitting someone at a hospital would lead to a lifetime of "See? You attacked me first!" debates?', 'Zap', 'First Meet') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-7', 'favorites', 'Juu’s Favorite Moment of the Day', 'That exact moment in the evening when both our works are done, phones connect, and you say: "Hey Juu..."', 'Moon', 'Pure Peace') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.little_things ("id", "category", "title", "description", "icon", "tag") VALUES ('thing-8', 'facts', 'A Truth Juu Keeps in Heart', 'No matter how chaotic the week gets, knowing I get to be in your corner makes everything worthwhile.', 'Shield', 'Unfiltered') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.future_dreams ("id", "title", "description", "location", "status", "category", "imageUrl") VALUES ('dream-1', 'A Peaceful Beach Night Ride (Done Right)', 'Cool sea breeze, slow quiet ride, stopping by the calm waves to hold hands under the stars, feeling safe, cherished, and completely at peace together.', 'Coastal Shoreline', 'planned', 'peace', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?q=80&w=800&auto=format&fit=crop') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.future_dreams ("id", "title", "description", "location", "status", "category", "imageUrl") VALUES ('dream-2', 'Watching a Golden Sunset Together', 'Sitting side by side on a quiet hill or seaside, watching the golden sky turn into deep navy without any rush to go anywhere.', 'Horizon Viewpoint', 'dreaming', 'quiet_days', 'https://images.unsplash.com/photo-1495616811223-4d98c6e9c869?q=80&w=800&auto=format&fit=crop') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.future_dreams ("id", "title", "description", "location", "status", "category", "imageUrl") VALUES ('dream-3', 'Celebrating Your Graduation & Achievements', 'Standing proudly in the crowd, cheering for you the loudest as you hold your degree and take big confident steps toward your dreams.', 'Your Convocation Hall', 'holding_close', 'celebration', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?q=80&w=800&auto=format&fit=crop') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.future_dreams ("id", "title", "description", "location", "status", "category", "imageUrl") VALUES ('dream-4', 'Exploring an Unfamiliar Cozy Town', 'Walking through quiet stone streets, finding little cafés, trying strange desserts, and laughing as we get delightfully lost together.', 'Hills or Historic Town', 'dreaming', 'adventure', 'https://images.unsplash.com/photo-1476514525535-07fb3b4ae5f1?q=80&w=800&auto=format&fit=crop') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.future_dreams ("id", "title", "description", "location", "status", "category", "imageUrl") VALUES ('dream-5', 'A Whole Day With Zero Rush', 'No alarms, no urgent calls, cooking together (or laughing at our burnt toast), watching favorite movies curled up in warm blankets.', 'Our Cozy Sanctuary', 'planned', 'quiet_days', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?q=80&w=800&auto=format&fit=crop') ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "description" = EXCLUDED."description";
INSERT INTO public.site_settings ("id", "entrancePassphraseHint", "heroTitle", "heroSubtitle", "welcomeMessage", "bgMusicEnabled") VALUES ('primary', 'laddu', 'Hey, my Laduuu...', 'Whenever You Need Me ❤️', 'If today feels a little heavy, stay here for a moment. This little world holds pieces of our story, my voice, our memories and everything I want you to remember.', false) ON CONFLICT ("id") DO UPDATE SET "heroTitle" = EXCLUDED."heroTitle";
